using System.Collections.Immutable;

namespace SharpMUSH.Library.ParserInterfaces;

/// <summary>A binding environment that distinguishes generated helper metadata from supplied aliases.</summary>
public sealed class AttributeArgumentEnvironment : Dictionary<string, CallState>
{
	public AttributeArgumentEnvironment() : base(StringComparer.OrdinalIgnoreCase) { }

	/// <summary>Keys generated by a signature rather than supplied by its caller.</summary>
	public HashSet<string> GeneratedKeys { get; } = new(StringComparer.OrdinalIgnoreCase);

	/// <summary>
	/// The key sets of plain positional calls (<c>0</c> to <c>n-1</c>), shared, since nearly every
	/// <c>u()</c> supplies exactly those.
	/// </summary>
	private static readonly ImmutableHashSet<string>[] PositionalKeys = [.. Enumerable.Range(0, 65)
		.Select(count => Enumerable.Range(0, count).Select(ParserState.ArgumentKey).ToImmutableHashSet(StringComparer.OrdinalIgnoreCase))];

	/// <summary>Capture keys without reading or evaluating any argument value.</summary>
	public static ImmutableHashSet<string> SuppliedKeys(IReadOnlyDictionary<string, CallState> arguments)
		=> arguments is not AttributeArgumentEnvironment && IsPositional(arguments)
			? PositionalKeys[arguments.Count]
			: arguments.Keys.Where(key => arguments is not AttributeArgumentEnvironment environment || !environment.GeneratedKeys.Contains(key))
				.ToImmutableHashSet(StringComparer.OrdinalIgnoreCase);

	private static bool IsPositional(IReadOnlyDictionary<string, CallState> arguments)
	{
		if (arguments.Count >= PositionalKeys.Length) return false;
		for (var position = 0; position < arguments.Count; position++)
		{
			if (!arguments.ContainsKey(ParserState.ArgumentKey(position))) return false;
		}

		return true;
	}
}
